mapper.select:
SELECT R.ID, R.EMBRYO_CODE, R.SCHEDULE_DATE, R.LH_MACHINE_CHANGE_MOLD_DESC, R.TASK_TYPE, R.PRODUCTION_STATUS, R.SPEC_DIMENSION, R.SINGLE_SHIFT_LH_QTY, NVL(SUM(P.MONTH_REMAIN_QTY), 0) MONTH_PLAN_OS FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_CX_MONTH_PLAN_SURPLUS P ON R.SAP_CODE = P.SAP_CODE AND P.YEAR = TO_CHAR(#{endDate}, 'YYYY') AND P.MONTH = TO_CHAR(#{endDate}, 'MM') AND P.DEL_FLAG = '0' WHERE R.DEL_FLAG = '0' AND R.LH_MACHINE_CHANGE_MOLD_DESC IS NOT NULL AND r.schedule_date BETWEEN #{startDate} AND #{endDate}
AND r.LH_MACHINE_NAME LIKE '%' || #{machineName} || '%'
GROUP BY R.ID, R.EMBRYO_CODE, R.SCHEDULE_DATE, R.LH_MACHINE_CHANGE_MOLD_DESC, R.TASK_TYPE, R.PRODUCTION_STATUS, R.SPEC_DIMENSION, R.SINGLE_SHIFT_LH_QTY ORDER BY schedule_date DESC
